#!/usr/bin/env python3
"""Generates the fragment shaders (one file per mode, no includes, so nothing depends on shader-define support)."""
import os, sys
out = sys.argv[1]

HEADER = """#version 330

// GENERATED by tools/gen_shaders.py - edit the template there, not this file.
// Every Ui shape is ONE quad. The vertex stage passes:
//   q     = -1..1 across the quad (set from the UVs: u,v = -1, region 2, texture 1)
//   gui   = GUI-space position of the pixel (so we can measure in GUI pixels without any uniform)
//   vData = packed colour: rgb keep their top 6 bits, the low 2 bits of r,g,b hold a 6-bit parameter (radius / spread),
//           alpha is the real alpha.
// The quad's half size in GUI px is recovered from screen-space derivatives, so no per-shape uniforms are needed.
uniform sampler2D Sampler0;   // unused dummy sampler (the GUI pipeline always binds one)

in vec2 q;
in vec2 gui;
in vec4 vData;

out vec4 fragColor;

float sdRoundBox(vec2 p, vec2 b, float r) {
    vec2 d = abs(p) - b + r;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;
}

float cover(float d, float aa) { return clamp(0.5 - d / aa, 0.0, 1.0); }

vec3 hsv2rgb(vec3 c) {
    vec3 p = abs(fract(c.xxx + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0);
    return c.z * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), c.y);
}

// soft organic edge: pushes the outline inwards by 0..2 GUI px, different lobes per window size
float blobWobble(vec2 p, vec2 hs) {
    float ang = atan(p.y / max(hs.y, 1.0), p.x / max(hs.x, 1.0));
    float ph = hs.x * 0.173 + hs.y * 0.091;
    float w = sin(ang * 3.0 + ph) * 0.55 + sin(ang * 5.0 - ph * 1.7) * 0.45;
    return 1.0 * (1.0 + w);
}

void main() {
    // derivatives first, before any branching
    // Jacobian d(gui)/d(q): works for rotated quads too (lines). Its column lengths are the half sizes in GUI px.
    vec2 gx = dFdx(gui), gy = dFdy(gui), qx = dFdx(q), qy = dFdy(q);
    float det = qx.x * qy.y - qx.y * qy.x;
    det = abs(det) < 1e-12 ? 1e-12 : det;
    vec2 col0 = (gx * qy.y - gy * qx.y) / det;
    vec2 col1 = (gy * qx.x - gx * qy.x) / det;
    vec2 hs = vec2(length(col0), length(col1));                                       // half size in GUI px
    float aa = max(length(gx), 1e-4);                                                 // GUI px per screen px

    ivec4 b = ivec4(vData * 255.0 + 0.5);
    int code = ((b.r & 3) << 4) | ((b.g & 3) << 2) | (b.b & 3);
    vec3 rgb = vec3(b.rgb & 252) / 252.0;
    float a = vData.a;
    vec2 p = q * hs;
    float edgeFade = 1.0 - smoothstep(0.80, 1.0, max(abs(q.x), abs(q.y)));   // glows fade out before the quad border
    vec4 t = texture(Sampler0, vec2(0.5));   // keeps the sampler alive; contributes nothing
    float keep = t.a * 0.0;
"""

MODES = {}

MODES["flat"] = """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
    fragColor = vec4(rgb, a * cover(d, aa) + keep);
}
"""

MODES["ramp_up"] = """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
    float k = smoothstep(0.0, 1.0, q.x * 0.5 + 0.5);
    fragColor = vec4(rgb, a * k * cover(d, aa) + keep);
}
"""

MODES["ramp_down"] = """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
    float k = 1.0 - smoothstep(0.0, 1.0, q.x * 0.5 + 0.5);
    fragColor = vec4(rgb, a * k * cover(d, aa) + keep);
}
"""

MODES["hue"] = """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
    vec3 c = hsv2rgb(vec3(clamp(q.x * 0.5 + 0.5, 0.0, 0.999), 0.85, 1.0));
    float edge = smoothstep(1.0, 0.0, abs(q.y)) * 0.18 + 0.82;   // slightly darker at the top / bottom edge
    fragColor = vec4(c * edge, a * cover(d, aa) + keep);
}
"""

MODES["wheel"] = """
    // colour wheel: hue = angle, saturation = distance from the centre, brightness = the packed 6-bit parameter
    float rad = min(hs.x, hs.y);
    float dist = length(p);
    float hue = fract(atan(p.y, p.x) / 6.28318530718 + 0.5);
    vec3 c = hsv2rgb(vec3(min(hue, 0.999), clamp(dist / rad, 0.0, 1.0), float(code) / 63.0));
    fragColor = vec4(c, a * cover(dist - rad, aa) + keep);
}
"""

# frosted body: vertical gradient + bright inner rim
def panel(blob):
    wob = "    d += blobWobble(p, hs);\n" if blob else ""
    return """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
%s    float cov = cover(d, aa);
    float y01 = q.y * 0.5 + 0.5;
    vec3 c = rgb * mix(1.14, 0.86, y01);
    float depth = max(-d, 0.0);
    float rim = exp(-depth / 2.2) * 0.30;
    float haze = exp(-depth / 14.0) * 0.07;                           // faint inner light that fades towards the middle
    c = mix(c, vec3(1.0), clamp(rim + haze, 0.0, 1.0));
    float a2 = clamp(a + rim * 0.55 + haze * 0.5, 0.0, 1.0);
    fragColor = vec4(clamp(c, 0.0, 1.0), a2 * cov + keep);
}
""" % wob

def ring(blob):
    wob = "    d += blobWobble(p, hs);\n" if blob else ""
    return """
    float r = min(float(code), min(hs.x, hs.y));
    float d = sdRoundBox(p, hs, r);
%s    float th = max(1.0, aa);
    float band = cover(d, aa) - cover(d + th, aa);
    fragColor = vec4(rgb, a * clamp(band, 0.0, 1.0) + keep);
}
""" % wob

# outer halo: the quad is the shape inflated by `spread`; code = spread/2 << 3 | radius/2
def glow(blob):
    wob = "    d += blobWobble(p, hi);\n" if blob else ""
    return """
    float spread = float(code >> 3) * 2.0 + 0.001;
    float r0 = float(code & 7) * 2.0;
    vec2 hi = max(hs - spread, vec2(1.0));
    float r = min(r0, min(hi.x, hi.y));
    float d = sdRoundBox(p, hi, r);
%s    float k = clamp(1.0 - d / spread, 0.0, 1.0);
    float halo = k * k * k;
    float inside = smoothstep(-aa, aa, d);                   // nothing under the panel itself
    fragColor = vec4(rgb, a * halo * inside + keep);
}
""" % wob


# radial menu ring slice. The quad is centred on the slice's circle and is (rOut + 8) px in half size.
# code = (rIn / rOut * 40) << 2 | sliceIndex(0 top, 1 lower right, 2 lower left)
SLICE_SETUP = """
    float pad = 8.0;
    float rOut = max(hs.x - pad, 1.0);
    float rIn = float(code >> 2) / 40.0 * rOut;
    int idx = code & 3;
    float ang = idx == 0 ? -1.5707963 : (idx == 1 ? 0.5235988 : 2.6179939);
    vec2 cdir = vec2(cos(ang), sin(ang));
    float len = length(p);
    float cosA = dot(p, cdir) / max(len, 1e-4);
    float halfA = 0.9774;                                              // 56 degrees each side of the slice centre
    float da = (acos(clamp(cosA, -1.0, 1.0)) - halfA) * len;           // px outside the wedge sides (negative inside)
    float rr = 5.0;                                                    // corner rounding
    float dr = max((rIn + rr) - len, len - (rOut - rr));
    vec2 w2 = vec2(dr, da + rr);
    float d = length(max(w2, 0.0)) + min(max(w2.x, w2.y), 0.0) - rr;
"""

MODES["slice"] = SLICE_SETUP + """
    float cov = cover(d, aa);
    float y01 = q.y * 0.5 + 0.5;
    vec3 c = rgb * mix(1.14, 0.86, y01);
    float depth = max(-d, 0.0);
    float rim = exp(-depth / 2.2) * 0.30;
    float haze = exp(-depth / 14.0) * 0.07;
    c = mix(c, vec3(1.0), clamp(rim + haze, 0.0, 1.0));
    float a2 = clamp(a + rim * 0.55 + haze * 0.5, 0.0, 1.0);
    fragColor = vec4(clamp(c, 0.0, 1.0), a2 * cov + keep);
}
"""

MODES["slice_ring"] = SLICE_SETUP + """
    float th = max(1.0, aa);
    float band = clamp(cover(d, aa) - cover(d + th, aa), 0.0, 1.0);
    float halo = exp(-max(d, 0.0) / 4.0) * 0.35 * edgeFade * smoothstep(-aa, aa, d);   // soft glow outside the edge
    fragColor = vec4(rgb, a * clamp(band + halo, 0.0, 1.0) + keep);
}
"""

# world-space chunk marker (squares / box faces / dots), drawn by WorldGfx in world coordinates.
# q = 0..1 across a square (edges glow at a constant pixel width, whatever the distance or angle), q.x >= 2 = a round dot.
# code = fillShare(0..15) << 2 | thickness(0..3)
WORLD = HEADER + """
    float fillK = float(code >> 2) / 15.0;
    float thick = (1.0 + float(code & 3)) * 1.5;
    if (q.x > 1.5) {                                   // dot
        vec2 l = (q - 2.0) * 2.0 - 1.0;
        float dd = length(l);
        float core = 1.0 - smoothstep(0.50, 0.70, dd);
        float halo = (1.0 - smoothstep(0.0, 1.0, dd)) * 0.45;
        fragColor = vec4(mix(rgb, vec3(1.0), core * 0.4), a * max(core, halo) + keep);
        return;
    }
    vec2 fw = abs(dFdx(q)) + abs(dFdy(q));              // uv change per screen pixel
    vec2 pe = min(q, 1.0 - q) / max(fw, vec2(1e-6));    // distance to each edge in screen px
    float e = min(pe.x, pe.y);
    float line = 1.0 - smoothstep(thick - 0.75, thick + 0.75, e);
    float glow = exp(-e / 7.0) * 0.50;
    float fill = fillK * (0.45 + 0.55 * exp(-e / 16.0));   // fuller towards the edges, like frosted glass
    float alpha = clamp(a * (line + glow * 0.7 + fill * 0.6), 0.0, 1.0);
    fragColor = vec4(mix(rgb, vec3(1.0), line * 0.35), alpha + keep);
}
"""

# anti-aliased line / capsule. The quad is rotated along the line by the GUI matrix, so p.x runs along it.
# code = half width in quarter px (0..63)
MODES["line"] = """
    float pad = 4.0;
    float w = max(float(code) * 0.25, 0.4);
    float d = sdRoundBox(p, vec2(max(hs.x - pad, 0.5), w), w);
    float cov = cover(d, aa);
    float glow = exp(-max(d, 0.0) / 2.2) * 0.22 * edgeFade * (1.0 - cov);
    fragColor = vec4(rgb, a * clamp(cov + glow, 0.0, 1.0) + keep);
}
"""

# organic blob (the reference menu): a distorted ellipse whose lobes are picked by a seed (code 0..63)
BLOBX_SETUP = """
    vec2 u = p / max(hs, vec2(1.0));
    float ang = atan(u.y, u.x);
    float sd = float(code);
    float rad = 0.74 + 0.070 * sin(3.0 * ang + sd * 0.37)
                     + 0.045 * sin(2.0 * ang + sd * 0.91 + 1.3)
                     + 0.030 * sin(5.0 * ang + sd * 1.73 + 2.1);
    float len = length(u);
    float dn = len - rad;
    vec2 gr = vec2(u.x / hs.x, u.y / hs.y) / max(len, 1e-4);
    float d = dn / max(length(gr), 1e-4);                                 // distance estimate in GUI px
"""

MODES["blobx"] = BLOBX_SETUP + """
    float cov = cover(d, aa);
    float y01 = q.y * 0.5 + 0.5;
    vec3 c = rgb * mix(1.12, 0.88, y01);
    float depth = max(-d, 0.0);
    float rim = exp(-depth / 3.0) * 0.22;
    float haze = exp(-depth / 24.0) * 0.08;
    c = mix(c, vec3(1.0), clamp(rim + haze, 0.0, 1.0));
    float a2 = clamp(a + rim * 0.5 + haze * 0.5, 0.0, 1.0);
    fragColor = vec4(clamp(c, 0.0, 1.0), a2 * cov + keep);
}
"""

MODES["blobx_ring"] = BLOBX_SETUP + """
    float th = max(2.0, aa);
    float band = clamp(cover(d, aa) - cover(d + th, aa), 0.0, 1.0);
    float halo = exp(-max(d, 0.0) / 6.0) * 0.55 * edgeFade * smoothstep(-aa, aa, d);   // wide soft glow outside the white edge
    float soft = exp(-max(-d, 0.0) / 5.0) * 0.18 * step(d, 0.0);            // faint inner glow
    fragColor = vec4(mix(rgb, vec3(1.0), band), a * clamp(band + halo + soft, 0.0, 1.0) + keep);
}
"""


# ---------------------------------------------------------------------------------------------------------------
# Ring segment (Blob UI hub, laid out like the radial menu). The quad is centred on the ring and is (rOut + 10) px in
# half size. code = (n - 2) << 3 | index   (n = number of segments 2..9, index 0..7; index 0 is at the top, clockwise)
# The inner radius is a fixed 56% of the outer radius. Corners are rounded generously and the outline carries a little
# per-segment wobble so every tab reads as a soft blob instead of a hard ring slice.
SEG_SETUP = """
    float pad = 10.0;
    float rOut = max(hs.x - pad, 1.0);
    float rIn = rOut * 0.56;
    int idx = code & 7;
    int n = ((code >> 3) & 7) + 2;
    float stepA = 6.2831853 / float(n);
    float ang = -1.5707963 + float(idx) * stepA;
    vec2 cdir = vec2(cos(ang), sin(ang));
    float len = length(p);
    float cosA = dot(p, cdir) / max(len, 1e-4);
    float rMid = 0.5 * (rIn + rOut);
    float halfA = 0.5 * stepA - 4.5 / rMid;                           // ~9 px gap between neighbouring tabs
    float da = (acos(clamp(cosA, -1.0, 1.0)) - halfA) * len;          // px outside the wedge sides (negative inside)
    float rr = 12.0;                                                  // big corner rounding
    float dr = max((rIn + rr) - len, len - (rOut - rr));
    vec2 w2 = vec2(dr, da + rr);
    float d = length(max(w2, 0.0)) + min(max(w2.x, w2.y), 0.0) - rr;
    float pa = atan(p.y, p.x);
    d += 0.9 * sin(pa * 6.0 + float(idx) * 2.3) + 0.5 * sin(pa * 11.0 - float(idx) * 1.7) - 0.4;
"""

MODES["seg"] = SEG_SETUP + """
    float cov = cover(d, aa);
    float depth = max(-d, 0.0);
    float lift = clamp(1.0 - (len - rIn) / max(rOut - rIn, 1.0), 0.0, 1.0);    // a touch brighter towards the middle
    vec3 c = rgb * (1.0 + 0.10 * lift);
    float rim = exp(-depth / 2.6) * 0.24;
    float haze = exp(-depth / 20.0) * 0.07;
    c = mix(c, vec3(1.0), clamp(rim + haze, 0.0, 1.0));
    float a2 = clamp(a + rim * 0.5 + haze * 0.5, 0.0, 1.0);
    fragColor = vec4(clamp(c, 0.0, 1.0), a2 * cov + keep);
}
"""

MODES["seg_ring"] = SEG_SETUP + """
    float th = max(1.6, aa);
    float band = clamp(cover(d, aa) - cover(d + th, aa), 0.0, 1.0);
    float halo = exp(-max(d, 0.0) / 5.0) * 0.45 * edgeFade * smoothstep(-aa, aa, d);
    fragColor = vec4(mix(rgb, vec3(1.0), band), a * clamp(band + halo, 0.0, 1.0) + keep);
}
"""

# ---------------------------------------------------------------------------------------------------------------
# Shader text: Sampler0 is a signed-distance-field glyph atlas (R = distance, 0.5 = edge). Bilinear filtering is done by
# hand with texelFetch so it works whatever filter mode the GUI gives the texture. The quad UVs are the real atlas UVs.
TEXT = """#version 330

// GENERATED by tools/gen_shaders.py - edit the template there, not this file.
uniform sampler2D Sampler0;   // SDF glyph atlas (tools/gen_sdf_font.py)

in vec2 q;
in vec2 gui;
in vec4 vData;

out vec4 fragColor;

void main() {
    ivec2 sz = textureSize(Sampler0, 0);
    vec2 st = q * vec2(sz) - 0.5;
    ivec2 i0 = ivec2(floor(st));
    vec2 f = fract(st);
    ivec2 hi = sz - ivec2(1);
    float s00 = texelFetch(Sampler0, clamp(i0, ivec2(0), hi), 0).r;
    float s10 = texelFetch(Sampler0, clamp(i0 + ivec2(1, 0), ivec2(0), hi), 0).r;
    float s01 = texelFetch(Sampler0, clamp(i0 + ivec2(0, 1), ivec2(0), hi), 0).r;
    float s11 = texelFetch(Sampler0, clamp(i0 + ivec2(1, 1), ivec2(0), hi), 0).r;
    float d = mix(mix(s00, s10, f.x), mix(s01, s11, f.x), f.y);
    float w = max(fwidth(d), 1e-4);                                   // distance change per screen pixel -> exact 1 px edge
    float cov = clamp((d - 0.48) / (0.85 * w) + 0.5, 0.0, 1.0);
    fragColor = vec4(vData.rgb, vData.a * cov);
}
"""

MODES["panel"] = panel(False)
MODES["panel_blob"] = panel(True)
MODES["ring"] = ring(False)
MODES["ring_blob"] = ring(True)
MODES["glow"] = glow(False)
MODES["glow_blob"] = glow(True)

os.makedirs(out, exist_ok=True)
for name, body in MODES.items():
    with open(os.path.join(out, "ui_%s.fsh" % name), "w") as f:
        f.write(HEADER + body)
with open(os.path.join(out, "world_marker.fsh"), "w") as f:
    f.write(WORLD)
with open(os.path.join(out, "ui_text.fsh"), "w") as f:
    f.write(TEXT)
print("wrote", len(MODES), "fragment shaders")
